import{_ as e}from"./chunks/update-designs-dialog.1cc98351.js";import{_ as t,o as s,c as a,Q as o}from"./chunks/framework.b67c47e6.js";const n="/assets/upload-level-groups.cfb6a46a.png",i="/assets/upload-documents.fdad227e.png",r="/assets/general-arrangement.61efca9c.svg",d="/assets/upload-auto-detect.87026517.png",l="/assets/files-table.958c803d.svg",h="/assets/status-to-split.885a30ee.svg",p="/assets/status-not-in-design.f558b276.svg",g="/assets/status-not-scanned.96c39212.svg",c="/assets/status-waiting.72842517.svg",m="/assets/status-splitting.5ddb2fb7.svg",u="/assets/status-split-failed.74e54607.svg",f="/assets/status-split.533ca22c.svg",w="/assets/status-in-design.b9e8a428.svg",y="/assets/status-scanned.bbcd6769.svg",b="/assets/older-export-warning.9ce1fe9e.png",v="/assets/file-messages.901d7703.png",x="/assets/files-set-category.5e91fa88.png",T="/assets/projects-settings-upload-detection.7a222207.png",k="/assets/designs-older-model.4020c77b.png",A="/assets/design-older-model-panel.bde668d9.png",F="/assets/assembly-type-icons.093a4608.png",I="/assets/design-type.816ab1d9.png",C="/assets/designs-set-type.4744a84e.png",_="/assets/set-type-dialog.e351c221.png",B=JSON.parse('{"title":"Files and Update designs","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/projects/index.md","filePath":"tutorials/projects/index.md","lastUpdated":1794068173000}'),D={name:"tutorials/projects/index.md"},S=o('<h1 id="files-and-update-designs" tabindex="-1">Files and Update designs <a class="header-anchor" href="#files-and-update-designs" aria-label="Permalink to &quot;Files and Update designs&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#upload-files">Upload Files</a><ul><li><a href="#auto-detect">Auto-detect</a></li><li><a href="#table-of-uploaded-files">Table of uploaded files</a></li><li><a href="#set-category">Set category</a></li><li><a href="#upload-detection">Upload detection</a></li></ul></li><li><a href="#update-designs">Update designs</a><ul><li><a href="#split-building-ifcs">Split building IFCs</a></li><li><a href="#create-and-revise-designs">Create and revise designs</a></li><li><a href="#link-details">Link details</a></li><li><a href="#analysis-prepare-the-viewer">Analysis (prepare the viewer)</a></li></ul></li></ul></nav><h2 id="upload-files" tabindex="-1">Upload Files <a class="header-anchor" href="#upload-files" aria-label="Permalink to &quot;Upload Files&quot;">​</a></h2><p>Files for each project are uploaded in <strong>Files</strong>, in the project menu under <strong>Designs</strong>:</p><p>Click <strong>Upload</strong>. The dialog starts with what the files are, on the left: <strong>Automatic</strong>, <strong>Project</strong>, <strong>Module</strong>, <strong>Assembly</strong> or <strong>Documents</strong>. With <strong>Automatic</strong>, the default, there is nothing else to choose: drop, paste or browse any mix of files, and each one goes to its file group by itself. See <a href="#auto-detect">Auto-detect</a>. Pick a level to choose the <strong>file group</strong> yourself, on the right: the list holds <em>Auto-detect</em> at that level and the groups of that level. Pick <strong>Documents</strong> for details, documentation and specifications, which have no level. Then drop or browse the files: the list under the drop zone says where each one goes. Click <strong>Upload</strong>. On a phone, the choice on the left is a list too. The dialog never asks a type: a design gets its type when it is analysed, or by hand. See <a href="#the-type-of-a-design">The type of a design</a>.</p><p>When the upload ends, the dialog shows how many files were uploaded and an <strong>Update designs</strong> button. Nothing runs on its own: you decide when the designs are updated, for example after the last of several uploads.</p><p><img src="'+n+'" alt="The upload dialog at Assembly: the buttons on the left and the file group list on the right, with Auto-detect (Assembly) and the assembly groups"></p><p>The file groups, by level:</p><ul><li><p><strong>Auto-detect</strong>: what <em>Automatic</em> does, and the first group at each level. Each file is sorted by its name. See <a href="#auto-detect">Auto-detect</a>.</p></li><li><p><strong>Assembly Files</strong>: Assembly IFCs (.ifc), Assembly BTLx (.btlx, only when <a href="/guide/management/btlx_designs/">BTLx designs</a> are switched on for your company), Extra Assembly IFCs (.ifc), Assembly drawings (.pdf), Machine Files (.jjs, .wup, .btl).</p></li><li><p><strong>Module Files</strong>: Module IFCs (.ifc), Extra Module IFCs (.ifc), Module drawings (.pdf).</p></li><li><p><strong>Project Files</strong>: Project IFCs (.ifc), External IFCs (.ifc), Project drawings (.pdf).</p></li><li><p><strong>Documents</strong>: Details (.pdf), Documentation (.pdf, .jpeg, .png), Specifications (.pdf, text). Documentation and specifications can also be added as text with the <strong>Add as text</strong> switch.</p></li></ul><p><img src="'+i+'" alt="The upload dialog at Documents: Details picked on the right, and three detail drawings listed with the group they go to"></p><p>The file name decides which design a file belongs to:</p><ul><li><p>IFCs: used for the 3D viewer, BoMs and machine files. The system reads them with the project&#39;s IFC Parsing Setup. The file name without extension is the design name. Example: &quot;PNL30-25.ifc&quot; belongs to design &quot;PNL30-25&quot;.</p></li><li><p>Extra IFCs: the design name is the part before the first &quot; - &quot;. Example: &quot;PNL30-25 - Installations.ifc&quot;.</p></li><li><p>Machine files: the file name without extension is the design name. Example: &quot;PNL30-25.btl&quot;.</p></li></ul><div class="info custom-block"><p class="custom-block-title">Full Project IFCs</p><p>You can also upload full project IFCs and the system can split them into one IFC per design. Upload them in the <strong>Project IFCs (.ifc)</strong> group. The file name does not matter. Example: &quot;OlaraAvenue15.ifc&quot;.</p></div><ul><li><p>Drawings: .pdf file format. They are shown in the viewer. The name of an assembly or module drawing must follow one of your company&#39;s <a href="#upload-detection">drawing name templates</a>. The one every company starts with is &quot;Merk DESIGN_NAME - DRAWING_NUMBER - DRAWING_NAME.pdf&quot;, where the word &quot;Merk&quot; at the start is optional. Example: &quot;Merk PNL30-25 - 1 - Zone 0 MAIN VIEW.pdf&quot;. A drawing whose name follows no template is not uploaded: the dialog names the file and the templates of your company. Project drawings are read the same way when their name follows a template, and are uploaded when it does not.</p></li><li><p>Details and documentation: .pdf file format. Also shown in the viewer. The file name without extension is the detail name that the system looks for in drawings. Example: &quot;V-12.pdf&quot;. Documentation files are linked to every design of the project.</p></li></ul><div class="info custom-block"><p class="custom-block-title">Full Project PDFs</p><p>In design mode, the viewer shows a &quot;General Arrangement&quot; entry at the top of the list. It opens the full project IFCs in 3D and the drawings uploaded as <strong>Project drawings (.pdf)</strong>, one button per drawing.</p><p><img src="'+r+'" alt="The viewer in design mode, on the General Arrangement"></p><ol><li>The list filter set to <strong>Design</strong>.</li><li>The <strong>General Arrangement</strong> entry.</li><li>The designs, with their revisions. Older revisions are red.</li><li><strong>3D</strong> and one button per project drawing.</li></ol></div><h3 id="auto-detect" tabindex="-1">Auto-detect <a class="header-anchor" href="#auto-detect" aria-label="Permalink to &quot;Auto-detect {#auto-detect}&quot;">​</a></h3><p>Auto-detect is what <strong>Automatic</strong> does, and the first entry of the file group list at each level. <em>Automatic</em> gives each IFC and drawing its level by your company&#39;s <a href="#upload-detection">levels and types detection</a>; at a level, every IFC and drawing is of that level. The dialog remembers your last choice on that browser. Then drop drawings, details, specs, documents and IFCs together. Before anything is uploaded, the dialog lists every file with what it was recognised as; change the level and the list changes with it. Nothing is read from inside a file: each one is sorted by its name and the level, by the first of these that applies:</p><ol><li><strong>A new version of a file already in the project</strong> goes where the earlier version went, with the same design.</li><li><strong>IFCs</strong> go to Project IFCs, Module IFCs or Assembly IFCs, by the level. With <em>Automatic</em>, the level is the one of the first rule that matches the file name, or the <em>Otherwise</em> level when none does. The file name without extension is the design name.</li><li><strong>BTLx files</strong> go to Assembly BTLx, when BTLx master files are on for your company.</li><li><strong>Drawings</strong> whose name follows one of your <a href="#upload-detection">drawing name templates</a> go to Project drawings, Module drawings or Assembly drawings, by the level, with the design they name. With <em>Automatic</em>, the rules are matched on that design name, <code>Merk M12 - 1 - Frame.pdf</code> on <code>M12</code>, and the <em>Otherwise</em> level applies when none matches. The design does not have to exist yet: the drawing is attached when <strong>Update designs</strong> makes it, as a drawing uploaded to its own group is.</li><li><strong>Details, specs and documents</strong> are recognised by your company&#39;s <a href="#upload-detection">other files detection</a>.</li><li><strong>Anything else</strong> goes to the <em>Otherwise</em> group of the other files detection, <em>Doc</em> to start with.</li></ol><p>So every file gets a group. To change one later, delete it and upload it again in the file group you want.</p><p>When you pick a level yourself, upload files of one level at a time: a panel IFC uploaded at <em>Project</em> becomes a Project IFC, and <strong>Update designs</strong> splits it. Extra IFCs, External IFCs and machine files are not recognised: pick their file group yourself, unless they are a new version of a file already in the project.</p><p><img src="'+d+'" alt="The upload dialog on Automatic: the Automatic, Project, Module, Assembly and Documents buttons, and each file listed with what it was recognised as"></p><p>When the upload ends, the dialog also says what was found, for example <em>3 drawings · 1 detail · 1 spec · 1 document · 2 model files</em>. Auto-detect does not start <strong>Update designs</strong>: you still decide when the designs are updated.</p><h3 id="table-of-uploaded-files" tabindex="-1">Table of uploaded files <a class="header-anchor" href="#table-of-uploaded-files" aria-label="Permalink to &quot;Table of uploaded files&quot;">​</a></h3><p>The table of files is shown below the upload summary. The summary counts the files, how many are linked to a design and how many name a design that does not exist, and shows the project&#39;s parsing setup with a link to change it.</p><p><img src="'+l+'" alt="The Files view"></p><ol><li><strong>Upload</strong> and <strong>Update designs</strong>. The number on Update designs counts the pending files.</li><li>The summary: files, files linked to a design, and files that name a design that does not exist.</li><li>The search, <strong>Only latest versions</strong> and <strong>Only design files</strong>.</li><li>The design of each file. A full IFC shows how many designs came out of it; an orange chip names a design that does not exist.</li><li>The status of each file, explained below.</li></ol><p>Use <strong>Filename search</strong> to filter the table, and <strong>Only latest versions</strong> to hide older versions of files uploaded again with the same name. Tick <strong>Only design files</strong> to list only the IFC and BTLx files. Select rows to delete, download or update designs from several files at once. The <strong>Design</strong> column shows the design each file is linked to.</p><p>Each file shows one status. The orange ones are pending: the next <strong>Update designs</strong> takes them in.</p><table><thead><tr><th>Status</th><th>Description</th></tr></thead><tbody><tr><td><img src="'+h+'" alt="To split"></td><td>A Project, External or Module IFC that has not been split yet.</td></tr><tr><td><img src="'+p+'" alt="Not in a design"></td><td>A design file (IFC, BTLx, drawing, machine file) that is not attached to its design yet.</td></tr><tr><td><img src="'+g+'" alt="Not scanned"></td><td>A drawing or detail that has not been scanned for detail names yet. A drawing only waits for this when the project has details or specs to find in it.</td></tr><tr><td><img src="'+c+'" alt="Waiting"></td><td>An update is running and works on this file. A file in this state cannot be deleted.</td></tr><tr><td><img src="'+m+'" alt="Splitting"></td><td>The file is being split. The percentage updates while the split runs.</td></tr><tr><td><img src="'+u+'" alt="Split failed"></td><td>The split failed for this file. Click the status to see its messages.</td></tr><tr><td><img src="'+f+'" alt="Split"></td><td>This full IFC has been split.</td></tr><tr><td><img src="'+w+'" alt="In a design"></td><td>The file is attached to its design.</td></tr><tr><td><img src="'+y+'" alt="Scanned"></td><td>The file has been scanned for detail names.</td></tr></tbody></table><p>The project menu shows the same number on <strong>Files</strong> from any page of the project, so you see that files are waiting without opening this view. While an update runs, the menu shows a spinner there, and a red mark if it failed.</p><h4 id="older-export" tabindex="-1">An older export uploaded after a newer one <a class="header-anchor" href="#older-export" aria-label="Permalink to &quot;An older export uploaded after a newer one {#older-export}&quot;">​</a></h4><p>Each IFC records the time it was exported, as written in the file. The time is read when the design made from the file is analysed (a building IFC when it is split). A new version of a file gets the next version number, in the order of the uploads, and a design takes the newest version. So an old export uploaded again by mistake would become the design&#39;s new revision.</p><p>When a version was exported <strong>before</strong> an earlier version of the same file, a warning icon sits next to its status. Hover it to see both export times, for example <em>Exported 2026-10-28 14:02, before version 2 of this file (exported 2026-10-30 09:15). Check that the right export was uploaded.</em></p><p><img src="'+b+'" alt="The Files table: version 3 of D10.ifc with a warning icon next to its status, and the tooltip giving both export times"></p><p>The same warning is in the file&#39;s <strong>Messages</strong>: click its status to open them. They also hold the warnings of a split. On a phone, tap the row, then its status.</p><p><img src="'+v+'" alt="The messages of D10.ifc: the warning that it was exported before version 2"></p><p>The warning does not block anything. The design shows it too, see <a href="#older-model">The model of this revision was exported before the previous one</a>. What to do:</p><ol><li>Check which export you uploaded, for example by the export time in your modelling program.</li><li>If it is the wrong one, delete that version in the table (<strong>⋮ → Delete</strong>), or upload the right export with the same name. The right export becomes a newer version, and the next <strong>Update designs</strong> gives the design a new revision from it.</li><li>If the older export is the one you want, do nothing.</li></ol><p>Files uploaded before this check existed have no export time and are not compared. BTLx files are not checked.</p><h3 id="set-category" tabindex="-1">Set category <a class="header-anchor" href="#set-category" aria-label="Permalink to &quot;Set category {#set-category}&quot;">​</a></h3><p>The <strong>Type</strong> column shows the file group of each file by its name. When Auto-detect chose it, the group has a wand mark; hover it to see why, for example <em>Drawing of W10</em>, <em>Level rule: W</em>, or <em>Sorted by the level chosen at upload</em>. A file still waiting in Auto-detect shows <em>Auto-detect</em>, and its state in the <strong>Status</strong> column.</p><p>A file left in Auto-detect by an upload made before every file was sorted shows <strong>Choose category</strong>. It is left out of <strong>Update designs</strong> until it has one, and the project menu counts it on <strong>Files</strong>.</p><p><strong>Set category</strong>, in the row menu or in the selection bar for several files, gives a file group to the files still waiting in Auto-detect, the ones that show <em>Choose category</em>. A file that already has its group keeps it, and Set category is not offered on it. A drawing must follow one of your drawing name templates to get a drawing group.</p><p>The table has no design type column: a design gets its type from its analysis or by hand, never from its files.</p><p><img src="'+x+'" alt="The Files table after an Auto-detect upload: drawings and IFCs sorted by the level rules, the tooltip of an IFC, a file in the fallback group Document, and an older file with Choose category and Set category in its row menu"></p><h3 id="upload-detection" tabindex="-1">Upload detection <a class="header-anchor" href="#upload-detection" aria-label="Permalink to &quot;Upload detection {#upload-detection}&quot;">​</a></h3><p><strong>Upload detection</strong> says how your company names the files it uploads. Open <strong>Projects Settings</strong> in the Settings section of the company menu, and expand <strong>Upload detection</strong>, just below <strong>Phase templates</strong>.</p><p>The card has three blocks, in this order.</p><p><strong>Levels and types detection</strong> gives each IFC and drawing its level for the <em>Automatic</em> level of the upload dialog, and each design the type it gets when <strong>Update designs</strong> creates it. Each rule has a level (<em>Project</em>, <em>Module</em> or <em>Assembly</em>), a type, a type of match (<em>Match full word</em>, <em>Match prefix</em> or <em>Contains word</em>) and a value. Case does not matter, and the rules are tried from the top:</p><ul><li>for the <strong>level</strong>, on the file name of an IFC, without its extension, and on the design name of a drawing; the first rule that matches gives the level;</li><li>for the <strong>type</strong>, on the design name, among the rules of the design&#39;s level; the first that matches gives the type.</li></ul><p><em>Generic</em> gives the level only, and a <em>Project</em> rule has no type. The last row, <strong>Otherwise</strong>, is the level and type when no rule matches: <em>Assembly</em> and <em>Generic</em> to start with. A company that makes one kind of panel only picks that type there and writes no rule. For example:</p><table><thead><tr><th>#</th><th>Level</th><th>Type</th><th>Match</th><th>Value</th></tr></thead><tbody><tr><td>1</td><td>Module</td><td>Module unit</td><td><em>Match prefix</em></td><td><code>M</code></td></tr><tr><td>2</td><td>Assembly</td><td>Timber exterior wall</td><td><em>Match prefix</em></td><td><code>BU</code></td></tr><tr><td>3</td><td>Assembly</td><td>Timber interior wall</td><td><em>Match prefix</em></td><td><code>BI</code></td></tr><tr><td>4</td><td>Assembly</td><td>Timber floor</td><td><em>Match prefix</em></td><td><code>VL</code></td></tr><tr><td>5</td><td>Assembly</td><td>Timber roof</td><td><em>Match prefix</em></td><td><code>HD</code></td></tr><tr><td>6</td><td><em>Otherwise</em> Assembly</td><td>Generic</td><td></td><td></td></tr></tbody></table><p><strong>Drawing name templates</strong> say how a drawing&#39;s name gives its design and drawing number. A template is written with these placeholders:</p><table><thead><tr><th>In a template</th><th>Means</th></tr></thead><tbody><tr><td><code>{design}</code></td><td>The design name. Required.</td></tr><tr><td><code>{number}</code></td><td>The drawing number. Required.</td></tr><tr><td><code>{name}</code></td><td>The drawing name. Optional.</td></tr><tr><td><code>*</code></td><td>Any text.</td></tr></tbody></table><p>Everything else in a template must be in the name as written. A template is compared with the whole file name without its extension, and case does not matter. Templates are tried from the top, and the first that matches wins. Drag them to change the order.</p><p><strong>Ignored words</strong> are left out at the start of the name, before the design.</p><p>Every company starts with the templates <code>{design} - {number} - {name}</code> and <code>{design} - {number}</code> and the ignored word <code>Merk</code>, which is what every drawing upload expected before. Add a template when your drawings are named another way:</p><table><thead><tr><th>Template</th><th>File name</th><th>Design</th><th>Drawing</th><th>Drawing name</th></tr></thead><tbody><tr><td><code>{design} - {number} - {name}</code></td><td><code>Merk D10 - 1 - Frame.pdf</code></td><td>D10</td><td>1</td><td>Frame</td></tr><tr><td><code>{design} - {number}</code></td><td><code>D10 - 2.pdf</code></td><td>D10</td><td>2</td><td></td></tr><tr><td><code>{design}_{number}</code></td><td><code>D10_3.pdf</code></td><td>D10</td><td>3</td><td></td></tr></tbody></table><p>Type a name in <strong>Try a file name</strong>, to the right of the rules (below them on a phone), to see how it is read before you save: the design, the drawing number, the level and the type it gets, for example <em>· level Assembly · type Timber exterior wall (level rule 2)</em>, or <em>(fallback)</em> when an <em>Otherwise</em> row decided.</p><p><strong>Other files detection</strong> recognises details, specs and documents for Auto-detect. Each rule has a file group (<em>Detail</em>, <em>Spec</em> or <em>Document</em>), a type of match (<em>Match full word</em>, <em>Match prefix</em> or <em>Contains word</em>) and a value, compared with the file name without its extension. The first rule that matches wins, for example <code>DET</code> with <em>Match prefix</em> for details and <code>Bestek</code> with <em>Contains word</em> for specs. The last row, <strong>Otherwise</strong>, is the group of a file nothing else recognises: <em>Doc</em> to start with.</p><p><img src="'+T+'" alt="The Upload detection card in Projects Settings: levels and types detection, drawing name templates with the ignored words, and other files detection, each rule block with its Otherwise row, and Try a file name on the right"></p><h2 id="update-designs" tabindex="-1">Update designs <a class="header-anchor" href="#update-designs" aria-label="Permalink to &quot;Update designs&quot;">​</a></h2><p><strong>Update designs</strong> brings the project&#39;s designs in line with its files. It runs three steps, in this order:</p><ol><li><a href="#split-building-ifcs">Split building IFCs</a>: Project, Module and External IFCs become one IFC per panel (and per module).</li><li><a href="#create-and-revise-designs">Create and revise designs</a>: designs are created and get the files that belong to them.</li><li><a href="#link-details">Link details</a>: drawings and IFCs are scanned for detail names.</li></ol><p>There is one button, <strong>Update designs</strong>, at the top of the table:</p><ul><li>With <strong>no file selected</strong> it works on every file of the project and does what is pending in them: the files with an orange status. The button shows how many there are. This is the usual way after an upload.</li><li>With <strong>files selected</strong> in the table it says <strong>Update designs from N files</strong> and works on those files only, and always does them, even if they were already done: for example to split a file again after deleting its outputs or after a fix, or to update only some designs. A Module IFC made by a split is split again too when you select it.</li></ul><p>It opens a dialog that shows what will happen before anything runs.</p><p><img src="'+e+'" alt="The Update designs dialog"></p><ol><li>What the update works on: all the files, with how many are pending, or the selected ones.</li><li>The splitting engine, see <a href="#split-building-ifcs">Split building IFCs</a>.</li><li>What each step will do: the files to split, the designs that are created or get a new revision, and the unbuilt units that move to the new revision.</li><li>The plan in one sentence, and the button. When units move, the button says how many.</li></ol><p>Each step has a switch. With selected files, every step that can take one of them starts on. With no selection, a step starts on when it has pending files, and off when it has none; the step then says what it already did, for example <em>Nothing pending · 2 building IFCs already split</em>. You can always turn it on: it then takes the files it already did again. This is what you need after changing the IFC Parsing Setup, when the building IFCs must be split again. To do only some files again, select them in the table. The settings are folded under the step, and the dialog opens with the settings of the project&#39;s last update.</p><p>While an update runs, the banner lists the three steps: a spinner on the one running, with its progress, a check on the ones done, and an empty circle on the ones waiting.</p><p>While the update runs, a banner above the table shows the step and its progress. When it ends, the banner shows how many designs are new or revised, which files could not be split, and the split warnings. The table, the designs and the counts reload on their own. Close the banner when you have read it.</p><p>Only one update runs in a project at a time. Production Counts stays open while the IFCs are split, and is locked while designs are created and revised, until the update ends: that step moves units and counts to the new revisions.</p><div class="tip custom-block"><p class="custom-block-title">The update stopped responding</p><p>An update reports its progress every minute. If it reports nothing for 30 minutes, the banner says <em>The update stopped responding</em> and offers <strong>Mark as stopped</strong>, which unlocks its files so you can start a new one. If it was still running after all, it finishes anyway.</p></div><h3 id="split-building-ifcs" tabindex="-1">Split building IFCs <a class="header-anchor" href="#split-building-ifcs" aria-label="Permalink to &quot;Split building IFCs&quot;">​</a></h3><p>Full IFCs are split into one IFC per design. The new files are added to the project as Assembly IFCs (and Module IFCs) and can be downloaded. The split also stores the quantity of each design and the phases and batches found in the IFC, so they are available in Production Counts. How assemblies are found in the IFC depends on the IFC Parsing Setup.</p><p>The split is available when the IFC splitter module is enabled for your company. The designs of the split files are created in the next step of the same update.</p><p>There are two engines:</p><ul><li><strong>Standard</strong>, recommended for Tekla, Revit, hsbCAD, cadwork, Vertex and AutoCAD Architecture, takes out everything the file holds: the modules, the assemblies in them and the assemblies at the project root. To leave modules or assemblies out, use the <a href="/guide/management/ifcps/#module-filter">Module filter</a> and the <a href="/guide/management/ifcps/#assembly-filter">Assembly filter</a> of the IFC Parsing Setup.</li><li><strong>Legacy</strong>, recommended only for some older Tekla and Revit export setups, makes one IFC per assembly. It cannot split a parsing setup that finds assemblies by a part property.</li></ul><p>A <strong>Module IFC</strong> you upload is split like a project IFC: it is a partial revision of the project, for example one module exported again. The file is the design file of its own module, so the split does not write that module out again: it takes out its assemblies, and any other module the file holds. The update makes the design of the module and of its assemblies. Without the splitter module an uploaded Module IFC is only a design file. Every Module and Assembly IFC, uploaded or made by a split, goes to the designs. When several files name the same design, the design takes the one exported last, by the time written in the IFC; of the versions of one file, the highest. If you upload a new version that was exported before the previous one, the Files table and the Designs list warn you: it is probably an old export uploaded by mistake. See <a href="#older-export">An older export uploaded after a newer one</a>.</p><p>A project keeps the engine it was split with. A project that was never split starts on <strong>Standard</strong>. If you switch engine on a project that was already split, the dialog warns you: design names can differ between engines, and designs that change name are created again.</p><div class="tip custom-block"><p class="custom-block-title">Settings</p><p>☑️ <strong>Skip standard library names</strong> Does not create IFCs for designs that already exist in the standard library.</p></div><p>If a file cannot be split, the other files go on, and the designs of the failed file are left as they were.</p><h3 id="create-and-revise-designs" tabindex="-1">Create and revise designs <a class="header-anchor" href="#create-and-revise-designs" aria-label="Permalink to &quot;Create and revise designs&quot;">​</a></h3><p>The system collects the IFCs, drawings and machine files and creates &quot;design&quot; objects.</p><ul><li><p>A list of design names is built from the file names of assembly and module IFCs, drawings and machine files.</p></li><li><p>Each file is attached to its design. All the documentation files are linked to every design, so they are always available.</p></li><li><p>When a design gets a new file, it gets a new revision, and its units that are not built yet move to the new revision.</p></li></ul><p>Units are not created here. Create them in <a href="/guide/quantities/">Production Counts</a> with <strong>Update production</strong>.</p><h4 id="older-model" tabindex="-1">The model of this revision was exported before the previous one <a class="header-anchor" href="#older-model" aria-label="Permalink to &quot;The model of this revision was exported before the previous one {#older-model}&quot;">​</a></h4><p>A design remembers when the model of each revision was exported. It is read when the design is analysed. The design panel shows it after the revision, <em>· Exported 2026-10-30 09:15</em>, and on each row of <strong>Other revisions</strong>. Revisions made before this was recorded show no export time.</p><p>When a new revision&#39;s model was exported <strong>before</strong> the model of the revision before it, the design gets a warning icon:</p><ul><li>in the <strong>Designs</strong> list, after the design&#39;s name;</li><li>in the design panel, after <em>Exported …</em>.</li></ul><p>Hover it to see both times: <em>The model of this revision was exported before the previous revision&#39;s (2026-10-28 14:02, previous 2026-10-30 09:15).</em> Nothing is stopped: the revision exists and its unbuilt units moved to it.</p><p><img src="'+k+'" alt="The Designs list: a warning icon after D10, with its tooltip"></p><p><img src="'+A+'" alt="The design panel of D10: Exported 2026-10-28 14:02 after the revision, the warning icon and its tooltip, and the export times of the other revisions"></p><p>What to do: open the design and compare the export times of its revisions. If the new revision came from the wrong export, upload the right one and run <strong>Update designs</strong> again: the design gets a new revision from it, and its unbuilt units move to it. See <a href="#older-export">An older export uploaded after a newer one</a>.</p><h4 id="the-type-of-a-design" tabindex="-1">The type of a design <a class="header-anchor" href="#the-type-of-a-design" aria-label="Permalink to &quot;The type of a design {#the-type-of-a-design}&quot;">​</a></h4><p>Each design has a type. An assembly design is Timber exterior wall, Timber interior wall, Timber roof, Timber floor, Timber panel, Steel wall, Steel cage or Concrete slab. A module design is Module unit. Production lines say which types they make. See <a href="/guide/management/production_lines/#the-production-line-form">Production Lines</a>.</p><p>No file brings a type. A design gets its type in these ways:</p><ul><li><strong>From its name, when it is created</strong>, by the <strong>Levels and types detection</strong> rules of <a href="#upload-detection">Upload detection</a>. A design no rule of its level matches gets the <em>Otherwise</em> type when the <em>Otherwise</em> level is its level, and <em>Generic</em> otherwise. A new revision keeps its type; one that is still <em>Generic</em> gets the type its name gives, so rules you add later reach the next revision.</li><li><strong>Corrected when it is analysed</strong>, by the <a href="/guide/management/ifcps/#assembly-type">Assembly type correction</a> and <a href="/guide/management/ifcps/#module-type">Module type correction</a> rules of the IFC Parsing Setup, when one matches. A design no rule matches keeps its type. These are not needed when your design names follow your level and type rules.</li><li><strong>By hand</strong>, with the <strong>Type</strong> in the design&#39;s details and its edit button, or with <strong>Set type</strong> in the <strong>Designs</strong> list.</li></ul><p>A type chosen by hand is never changed by the analysis, by a new revision or by the rules. A subassembly gets its type from its panel&#39;s analysis. <em>Timber panel</em> is a timber panel of none of the four kinds: designs made before the four types existed have it.</p><p>The type also decides how a design is analysed: a design typed <em>Steel cage</em> is analysed as a steel cage. When the rules or a person change a design to or from <em>Steel cage</em>, it is analysed again.</p><p>Each type has its own icon, shown before the design&#39;s name in the <strong>Designs</strong> and <strong>Constructibles</strong> lists, in their details and in the viewer&#39;s list. A unit shows the icon of its design&#39;s type.</p><p><img src="'+F+'" alt="The icon of each type: Generic, Timber exterior wall and Timber panel share the wall frame; interior wall, roof, floor, steel wall, steel cage, concrete slab, subassembly and module unit each have their own"></p><p><img src="'+I+'" alt="The type of a design in its details, with the edit window open on the assembly types, Generic first"></p><h5 id="set-type" tabindex="-1">Set type <a class="header-anchor" href="#set-type" aria-label="Permalink to &quot;Set type {#set-type}&quot;">​</a></h5><p>In the <strong>Designs</strong> list, <strong>Set type</strong> sets the type of one design (in the <strong>⋮</strong> menu of its row) or of the selected designs (in the bar above the list). On a phone, tap <strong>Select</strong>, pick the designs, and <strong>Set type</strong> is in <strong>Actions</strong>.</p><p><img src="'+C+'" alt="The Designs list: three designs selected, Set type above the list, and Set type in the row menu of D12"></p><p>The window has one type list per level: <strong>Assembly type</strong> for the assembly designs and <strong>Module type</strong> for the module designs. It opens on the type the designs share, and on nothing when they differ. <strong>Save</strong> sets the type as a choice made by hand. A subassembly in the selection is listed in the window and keeps its type.</p><p><img src="'+_+'" alt="The Set design type window: the assembly types with Generic first, and a note that the subassembly D11-S1 keeps its type"></p><div class="tip custom-block"><p class="custom-block-title">Settings</p><p>☑️ <strong>Keep revision numbers</strong> Designs keep their revision number when they get new files.</p><p>☑️ <strong>Draw from IFC</strong> Generates drawings from the IFC of each design, with the default set of views.</p></div><h3 id="link-details" tabindex="-1">Link details <a class="header-anchor" href="#link-details" aria-label="Permalink to &quot;Link details&quot;">​</a></h3><p>Details can be automatically detected in IFCs and PDF drawings. Found detail names are linked to the design and then shown in the viewer. Only the drawings that were not scanned yet are scanned; when a new detail is uploaded, every drawing is scanned again for it. In a project with no details and no specs, drawings are not scanned and do not count as pending.</p><div class="tip custom-block"><p class="custom-block-title">Settings</p><p>☑️ <strong>Scan drawings</strong> Drawings are scanned to find detail and specification names, and details are scanned to find specification names. On by default.</p><p>☑️ <strong>Scan IFCs</strong> IFCs are scanned for detail names in the property &quot;DET_NUMBER&quot;.</p></div><p>If your detail names can&#39;t be detected by the system, you may have a rasterized export, or a rasterized font in a vectorized export, such as the <a href="https://www.autodesk.com/support/technical/article/caas/sfdcarticles/sfdcarticles/How-to-create-selectable-and-searchable-text-in-a-PDF-from-AutoCAD.html" target="_blank" rel="noreferrer">well known issue with AutoCad</a>.</p><h3 id="analysis-prepare-the-viewer" tabindex="-1">Analysis (prepare the viewer) <a class="header-anchor" href="#analysis-prepare-the-viewer" aria-label="Permalink to &quot;Analysis (prepare the viewer)&quot;">​</a></h3><p>The analysis starts automatically when a design gets a new IFC, for example after Update designs. It also sets the <a href="#the-type-of-a-design">type of the design</a> from the IFC Parsing Setup&#39;s rules, and reads when its model was exported. There is no button for it in the Update designs dialog. If the company setting <strong>Launch analysis automatically</strong> is off, or you need to run it again, select the designs in <strong>Designs</strong> and click <strong>Force analysis</strong>. The <strong>Analysis</strong> column of the designs table shows the status of each design.</p><div class="warning custom-block"><p class="custom-block-title">Slow task!</p><p>⚠️ This operation takes time. It runs many heavy computations and database tasks.</p></div><ul><li><p>IFC geometry is analyzed to find the rotation and translation matrices (orientation of the panel in the world coordinate system).</p></li><li><p>Panel size and bruto/neto areas are also calculated here. So if you use bruto areas in Production Counts, you need to wait for this operation.</p></li><li><p>Each part of the IFC is analyzed, generating drawings and metadata which are saved in the database. This gives fast access to the information when the user clicks on a part in the 3D viewer.</p></li><li><p>Drawings are only generated for wood and plate parts, and for parts in custom branches marked for logistics in the IFC Parsing Setup. So, if your IFC Parsing Setup is incomplete, some part drawings may be missing.</p></li></ul>',118),P=[S];function q(j,M,U,E,W,O){return s(),a("div",null,P)}const G=t(D,[["render",q]]);export{B as __pageData,G as default};
